create extension if not exists pgcrypto;
create table profiles(id uuid primary key references auth.users on delete cascade,full_name text,role text not null default 'user' check(role in('user','admin')),created_at timestamptz default now(),updated_at timestamptz default now());
create or replace function is_admin() returns boolean language sql security definer stable as $$ select exists(select 1 from profiles where id=auth.uid() and role='admin') $$;
create table genres(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,artwork_key text,is_active boolean default true,created_at timestamptz default now());
create table songs(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,artist text not null,description text,genre_id uuid references genres on delete set null,mood text,language text,audio_key text not null,artwork_key text,duration int,file_size bigint,status text not null default 'draft' check(status in('draft','published')),is_featured boolean default false,play_count int default 0,download_count int default 0,usage_rights text,attribution_text text,seo_title text,seo_description text,youtube_video_id text,created_at timestamptz default now(),updated_at timestamptz default now());
create index on songs(status,created_at desc);create index on songs(genre_id);
create table playlists(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,description text,artwork_key text,is_featured boolean default false,is_published boolean default false,created_at timestamptz default now());
create table playlist_songs(id uuid primary key default gen_random_uuid(),playlist_id uuid references playlists on delete cascade,song_id uuid references songs on delete cascade,position int not null,unique(playlist_id,song_id));
create table videos(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,description text,youtube_url text not null,youtube_video_id text unique not null,thumbnail_url text,duration int,published_at timestamptz,video_type text default 'video' check(video_type in('video','short')),song_id uuid references songs on delete set null,is_featured boolean default false,status text not null default 'draft' check(status in('draft','published')),source text default 'manual' check(source in('manual','channel_sync')),created_at timestamptz default now(),updated_at timestamptz default now());
create table affiliate_networks(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,programme_identifier text,integration_type text default 'manual',status text default 'inactive',terms_url text,last_sync_at timestamptz,created_at timestamptz default now());
create table affiliate_categories(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,is_active boolean default true);
create table affiliate_products(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,brand text,category_id uuid references affiliate_categories,network_id uuid not null references affiliate_networks,affiliate_url text not null check(affiliate_url ~ '^https?://'),original_url text,image_url text,image_source text,image_permission text,price numeric,currency text default 'INR',price_last_verified_at timestamptz,is_featured boolean default false,is_active boolean default true,is_published boolean default false,display_order int default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table affiliate_clicks(id uuid primary key default gen_random_uuid(),product_id uuid references affiliate_products on delete set null,network_id uuid references affiliate_networks,clicked_at timestamptz default now(),referrer text,device_type text,anonymous_session_id text);
create table affiliate_commissions(id uuid primary key default gen_random_uuid(),network_id uuid references affiliate_networks,product_id uuid references affiliate_products on delete set null,external_order_reference text,order_amount numeric,commission_amount numeric,currency text default 'INR',status text default 'pending' check(status in('pending','approved','rejected','paid')),reported_at timestamptz,confirmed_at timestamptz,paid_at timestamptz);
create table downloads(id uuid primary key default gen_random_uuid(),song_id uuid references songs on delete cascade,downloaded_at timestamptz default now(),anonymous_session_id text);
create table site_settings(id uuid primary key default gen_random_uuid(),setting_key text unique not null,setting_value jsonb not null,updated_at timestamptz default now());
create table audit_logs(id uuid primary key default gen_random_uuid(),admin_user_id uuid,action text,entity_type text,entity_id text,details jsonb,created_at timestamptz default now());
do $$ declare t text; begin foreach t in array array['profiles','genres','songs','playlists','playlist_songs','videos','affiliate_networks','affiliate_categories','affiliate_products','affiliate_clicks','affiliate_commissions','downloads','site_settings','audit_logs'] loop execute format('alter table %I enable row level security',t); execute format('create policy "admin all" on %I for all using(is_admin()) with check(is_admin())',t); end loop; end $$;
create policy "public songs" on songs for select using(status='published');
create policy "public genres" on genres for select using(is_active);
create policy "public playlists" on playlists for select using(is_published);
create policy "public playlist_songs" on playlist_songs for select using(true);
create policy "public videos" on videos for select using(status='published');
create policy "public products" on affiliate_products for select using(is_published and is_active);
create policy "public networks" on affiliate_networks for select using(true);
create policy "public cats" on affiliate_categories for select using(is_active);
create policy "public settings" on site_settings for select using(setting_key in('youtube','site'));
create policy "own profile" on profiles for select using(id=auth.uid());
insert into affiliate_networks(name,slug) values('Amazon Associates India','amazon'),('Meesho','meesho');
